COMPANIES = ['Điện toán Bình Minh','Thương mại Sen','An toàn thông tin Lam','Thiết kế Mây','Truyền thông Bình Minh']

def localize(scenario):
    for candidate, content in zip(scenario['candidates'], CANDIDATES, strict=True):
        candidate.update(content)
    targets = scenario['jobs'] + [c['job'] for c in scenario['companies']]
    for job, content in zip(targets, JOBS, strict=True):
        job.update(content)
        if job['workMode'] == 'Hybrid':
            job['workMode'] = 'Kết hợp tại văn phòng và từ xa'
        if job.get('category') == 'Marketing':
            job['category'] = 'Tiếp thị'
        if job not in scenario['jobs']:
            job['benefits'] = f"Tin mẫu để kiểm tra bộ lọc; mức lương {job['salaryMin']}–{job['salaryMax']} triệu đồng/tháng chỉ mang tính minh họa. Được hướng dẫn nghiệp vụ và đào tạo chuyên môn."
    for company, name in zip(scenario['companies'], COMPANIES, strict=True):
        company['name'] = name
    return scenario

if __name__ == '__main__':
    root = Path(__file__).resolve().parents[2]
    path = Path(__file__).with_name('scenario.json')
    backup = root / 'webAI/App_Data/backups' / ('noi-dung-' + datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S'))
    backup.mkdir(parents=True, exist_ok=True)
    shutil.copy2(path, backup / 'scenario-truoc-viet-hoa.json')
    result = localize(json.loads(path.read_text(encoding='utf-8')))
    path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8', newline='\n')
    print('Vietnamese scenario prepared; research data and model weights unchanged.')
